import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const script = fileURLToPath(new URL('../quantity.mjs', import.meta.url));

function run(input) {
  const r = spawnSync(process.execPath, [script], { input, encoding: 'utf8', timeout: 5000 });
  assert.equal(r.error, undefined, `failed to run quantity.mjs: ${r.error}`);
  const out = r.stdout.trim();
  let parsed;
  assert.doesNotThrow(() => { parsed = JSON.parse(out); }, `stdout is not JSON: ${JSON.stringify(out)}`);
  return parsed;
}

test('quantity.mjs exists', () => {
  assert.ok(existsSync(script), 'quantity.mjs must exist at the repository root');
});

const valid = [['2', 2], ['1', 1], ['42\n', 42], ['  7  \n', 7]];
for (const [input, expected] of valid) {
  test(`positive integer ${JSON.stringify(input)} -> {"quantity":${expected}}`, () => {
    assert.deepEqual(run(input), { quantity: expected });
  });
}

const invalid = ['0', '-1', '-5\n', '1.5', '0.25', '2.7\n'];
for (const input of invalid) {
  test(`invalid ${JSON.stringify(input)} -> {"error":"invalid_quantity"}`, () => {
    assert.deepEqual(run(input), { error: 'invalid_quantity' });
  });
}
